// === Tab: mySketch.js ===
let time = 0; // Tracks time for animation
let spiralImg; // Variable to hold the image

function preload() {
  // Load the image before the sketch starts
  spiralImg = loadImage('https://openprocessing.org/sketch/2495641/files/spiral.png');
}

function setup() {
  createCanvas(windowHeight*4/3, windowHeight);
	colorMode(HSB, 255);
  noFill();
  stroke(255);
  background(0);
}

function draw() {
  background(0, 50); // Create motion trails
  translate(width / 2, height / 2); // Center the coordinate system
  strokeWeight(2);

  // Draw the animated spirals
  for (let i = 0; i < 100; i++) {
    let angle = i * TWO_PI / 30 + time * 0.01;
    let radius = i * 10 + sin(time * 0.05 + i) * 30;
    let distortion = sin(time * 0.1 + i) * 20;
    let noiseFactor = noise(i * 0.1, time * 0.01) * 20;
    stroke((40+(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))/3)%255, 150, 255)
    beginShape();
    for (let a = 0; a < TWO_PI; a += 0.1) {
      let x = (radius + distortion + noiseFactor) * cos(a + angle);
      let y = (radius + distortion + noiseFactor) * sin(a + angle);
      vertex(x, y);
    }
    endShape(CLOSE);
  }

  // Display spiral.png at the bottom center
  imageMode(CENTER);
  let imgX = 0; // Centered horizontally
  let imgY = (height / 2) - (spiralImg.height / 2); // Positioned at the bottom
	tint((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))/3%255, 150, 255)
  image(spiralImg, imgX, imgY);

  time += 1; // Advance time for animation
}

function keyPressed(){
  save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
}

